static std::random_device rd;
static std::mt19937 gen(rd());
int inside = 0, outside = 0;

// Create random directions using spherical coordinates
std::uniform_real_distribution<> theta_dist(0.0, 2.0 * M_PI);
std::uniform_real_distribution<> phi_dist(0.0, M_PI);

for (int i = 0; i < numberOfChecks; i++) {
    // Generate random direction
    double theta = theta_dist(gen);
    double phi = phi_dist(gen);

    // Convert spherical to Cartesian coordinates
    double x = std::sin(phi) * std::cos(theta);
    double y = std::sin(phi) * std::sin(theta);
    double z = std::cos(phi);

    // Create ray from point p in random direction
    K::Ray_3 ray(CGALPoint(p.x(), p.y(), p.z()),
                 CGALPoint(p.x() + x, p.y() + y, p.z() + z));

    // Count intersections
    int intersections = tree.number_of_intersected_primitives(ray);

    // Check if number of intersections is odd (point is inside)
    if (intersections % 2 == 1) {
        inside++;
    } else {
        outside++;
    }
}

// Return true if majority of rays indicate inside
return inside > outside;

